mapper.select:
SELECT alert_id, idempotency_key, payload_hash, organization_id, location_id, device_uuid,
    alert_type, severity, status, rule_id, occurred_at, created_at,
    lambda_assignment_id, lambda_id, lambda_version_id, run_id, event_key, changes_json
FROM lambda_alerts
WHERE idempotency_key = #{idempotencyKey}
  AND lambda_assignment_id = #{lambdaAssignmentId}
